css:
.capabilities__button {
  flex: 0 0 auto;
  align-self: flex-start;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  min-height: 48px;
  padding: 0 20px;
  border: 1px solid rgb(17 17 17 / 0.1);
  border-radius: 999px;
  background: rgb(255 255 255 / 0.78);
  color: #111111;
  font-size: 14px;
  font-weight: 700;
  box-shadow:
    inset 0 1px 0 rgb(255 255 255 / 0.95),
    0 18px 44px rgb(31 44 44 / 0.08);
}
